// === Tab: mySketch.js ===
//Fork of https://openprocessing.org/sketch/2714361
//BG Youtube Audio: https://youtu.be/C7HL5wYqAbU?si=AqUNGcmRpiJM1602
let step = 10;   // grid spacing
let margin = 10;  // offset from edges
function setup()
{
  createCanvas(windowWidth, windowHeight);
}
function draw()
{
	frameRate(7)
	step+=.1
	for (let row = 0; row < 70; row++)
	{
		for (let col = 0; col < 70; col++)
		{
			margin=random(40)
			let x = margin + col * step;
			let y = margin + row * step;
			rotate(step/5)
			stroke(random(255), random(255), random(255));
			strokeWeight(row/50+step/random(300));
			line(x, y, x + step, y + step/5*row);  // short diagonal
		}
	}
}

